struct BoardData {
    int balance;
    int speed;
    int air;
    int spin;
    int height_feet;
    int height_inches;
    int width;
    float thickness;
    int tail_type;
};

class FEEntityManager {
public:
    void UpdateBoardIndex(int board, int tail_type, int size, bool draw);
};

class FEManager {
    char pad[12];
public:
    FEEntityManager *em;
};

class PanelQuad {
    char pad[0x194];
public:
    virtual ~PanelQuad();
    virtual void Init();
    virtual void TurnOn(bool enabled);
};

class UnlockingManager {
public:
    bool isSurferBoardUnlocked(int surfer, int board) const;
};

class BoardFrontEnd {
    char pad0[0x13c];
    FEManager *manager;
    bool unlocked;
    char pad1[3];
    void *sys;
    int current_board_index;
    char pad2[0x260 - 0x16c];
    PanelQuad *line_a;
    PanelQuad *line_b;
    char pad3[0x270 - 0x268];
    int surfer_index;
public:
    enum { ROUND };
    bool IsLevelBoardUnlocked(int location);
    void OnHighlightBoard();
    void SetDisplay(BoardData bd);
};

extern BoardData SurferBoardArray[15][9];
extern BoardData LocationBoardArray[17];
extern UnlockingManager unlockManager;

#define MAX_BOARDS 9
#define MAP_LOC_LAST 17

void BoardFrontEnd::OnHighlightBoard()
{
	int maxBoards = MAX_BOARDS+MAP_LOC_LAST;

	BoardData bd;

	if (current_board_index >= MAX_BOARDS)
		bd = LocationBoardArray[current_board_index - MAX_BOARDS];
	else
		bd = SurferBoardArray[surfer_index][current_board_index];

	int size = bd.height_feet * 12 + bd.height_inches;
	manager->em->UpdateBoardIndex(current_board_index, ROUND, size, false);
	if (current_board_index < MAX_BOARDS)
	{
		unlocked = unlockManager.isSurferBoardUnlocked(surfer_index, current_board_index);
	}
	else
	{
		unlocked = IsLevelBoardUnlocked(current_board_index - MAX_BOARDS);
	}

	line_a->TurnOn(unlocked);
	line_b->TurnOn(unlocked);

	SetDisplay(bd);
}
